      "keystrokes": "cat << 'EOF' > convert_essays.py
import requests
import os
from bs4 import BeautifulSoup

def get_essay_text(url):
    headers = {'User-Agent': 'Mozilla/5.0'}
    response = requests.get(url, headers=headers)
    soup = BeautifulSoup(response.text, 'html.parser')
    # Paul Graham's essays are usually in a <font size="2" face="verdana"> tag
    font_tag = soup.find('font', {'size': '2', 'face': 'verdana'})
    if font_tag:
        # Remove script and style elements
        for script_or_style in font_tag(["script", "style"]):
            script_or_style.decompose()
        return font_tag.get_text(separator=' ', strip=True)
    return soup.get_text(separator=' ', strip=True)

essays = [
    "http://www.paulgraham.com/ds.html",
    "http://www.paulgraham.com/foundermode.html"
]

combined_text = ""
for url in essays:
    print(f"Fetching {url}...")
    text = get_essay_text(url)
    combined_text += text + "\n\n"

# OpenAI TTS API has a limit of 4096 characters per request.
# If the text is longer, we might need to split it.
# Let's check the length.
print(f"Total length: {len(combined_text)} characters")

api_key = os.getenv("OPENAI_API_KEY")
if not api_key:
    print("Error: OPENAI_API_KEY not found.")
    exit(1)

# Splitting text into chunks of 4000 characters to be safe
chunks = [combined_text[i:i+4000] for i in range(0, len(combined_text), 4000)]

audio_parts = []
for i, chunk in enumerate(chunks):
    print(f"Converting chunk {i+1}/{len(chunks)} to speech...")
    response = requests.post(
        "https://api.openai.com/v1/audio/speech",
        headers={"Authorization": f"Bearer {api_key}"},
        json={
            "model": "tts-1",
            "input": chunk,
            "voice": "alloy"
        }
    )
    if response.status_code == 200:
        audio_parts.append(response.content)
    else:
        print(f"Error from OpenAI API: {response.status_code} - {response.text}")
        exit(1)

with open("/root/audiobook.mp3", "wb") as f:
    for part in audio_parts:
        f.write(part)

print("Audiobook saved to /root/audiobook.mp3")
EOF
